WITH lines AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) t AS element) SELECT CASE WHEN element >= 76 THEN 'HIGH' ELSE 'LOW' END AS element_tier, currency, MAX(element) FILTER (WHERE plan = 'enterprise') AS enterprise_max_element, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN plan = 'enterprise' THEN 1 END), 0), 2) AS element_per_enterprise, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, MIN(element) AS min_element, DENSE_RANK() OVER (PARTITION BY CASE WHEN element >= 76 THEN 'HIGH' ELSE 'LOW' END ORDER BY MIN(element) DESC) AS min_element_dense_rank FROM lines GROUP BY CASE WHEN element >= 76 THEN 'HIGH' ELSE 'LOW' END, currency ORDER BY enterprise_max_element DESC NULLS LAST;
